steps.script:
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
GameState.state.players["1"]["cp"] = 0
GameState.state.players["2"]["cp"] = 0
H.move_to("U_GRETCHIN_C", 38.0, 38.5)
PhaseManager.transition_to_phase(9)
return load("res://scripts/codex/space_wolves/SWDetachments11e.gd").charge_reroll_source(GameState.state.units["U_ARJAC_ROCKFIST_A"])

var cc = tree.root.get_node("Main").charge_controller
var out = []
for i in range(cc.unit_selector.get_item_count()):
	out.append(str(cc.unit_selector.get_item_metadata(i)))
print("[sw11e preyslayer] charge list: ", out)
return out.find("U_ARJAC_ROCKFIST_A")

var t: String = tree.root.get_node("CommandRerollDialog").find_child("HeaderLabel", true, false).text
print("[sw11e preyslayer] reroll header: ", t)
return t.contains("PREYSLAYER") and t.contains("FREE RE-ROLL")

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[sw11e log] ", DebugLogger.get_real_log_file_path(), " ERROR lines = ", n, " ", bad.slice(0, 3))
return n
